'use client'

import * as React from 'react'
import {
  useReactTable,
  getCoreRowModel,
  getPaginationRowModel,
  ColumnDef,
  flexRender,
} from '@tanstack/react-table'
import { useGetSellerSales } from '@/lib/handleAllGetRequests'
import { Sale } from '@/../types/sales'
import TableSkeleton from '@/components/reusable/TableSkeleton'
import ErrorState from '@/components/reusable/ErrorState'

const columns: ColumnDef<Sale>[] = [
  { header: 'Product ID', accessorKey: 'productId' },
  { header: 'Quantity', accessorKey: 'quantity' },
  {
    header: 'Date',
    accessorFn: (row) =>
      new Date(row.date).toLocaleDateString('en-US', {
        month: '2-digit',
        day: '2-digit',
        year: 'numeric',
      }) +
      '\n' +
      new Date(row.date).toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: true,
      }),
  },
  { header: 'Total Sell Amount', accessorKey: 'totalSellAmount' },
  {
    header: () => (
      <span>
        Admin Charge <span className="text-green-500">(4.99%)</span>
      </span>
    ),
    accessorKey: 'adminCharge',
  },
  { header: 'My Revenue', accessorKey: 'myRevenue' },
]

export default function SalesTable() {
  const { data, isLoading, isError } = useGetSellerSales()
  const sales = data?.data?.salesHistory || []

  const table = useReactTable({
    data: sales,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageSize: 8 } },
  })

  if (isLoading) return <TableSkeleton />
  if (isError) return <ErrorState message="Failed to load sales history" />

  return (
    <div className="bg-transparent border rounded-lg">
      <table className="w-full text-left">
        <thead>
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <th
                  key={header.id}
                  className="px-4 py-3 text-base font-medium text-[#272727]"
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext()
                  )}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id} className="border-t">
              {row.getVisibleCells().map((cell) => (
                <td
                  key={cell.id}
                  className="px-4 py-3 text-base text-[#595959] whitespace-pre-line"
                >
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {/* pagination */}
      <div className="flex items-center justify-between bg-white border-t px-6 py-3 text-sm">
        <div className="text-[#707070] font-medium">
          Showing{' '}
          {table.getState().pagination.pageIndex *
            table.getState().pagination.pageSize +
            1}{' '}
          to{' '}
          {Math.min(
            (table.getState().pagination.pageIndex + 1) *
              table.getState().pagination.pageSize,
            sales.length
          )}{' '}
          of {sales.length} results
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            className={`w-[32px] h-[32px] rounded-md text-white text-sm font-medium
              ${
                table.getCanPreviousPage()
                  ? 'bg-[#797068]'
                  : 'bg-gray-300 cursor-not-allowed'
              }`}
          >
            {'<'}
          </button>

          {Array.from({ length: table.getPageCount() }, (_, i) => (
            <button
              key={i}
              onClick={() => table.setPageIndex(i)}
              className={`w-[32px] h-[32px] rounded-md text-white text-sm font-medium
                ${
                  table.getState().pagination.pageIndex === i
                    ? 'bg-[#797068]'
                    : 'bg-gray-300'
                }`}
            >
              {i + 1}
            </button>
          ))}

          <button
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            className={`w-[32px] h-[32px] rounded-md text-white text-sm font-medium
              ${
                table.getCanNextPage()
                  ? 'bg-[#797068]'
                  : 'bg-gray-300 cursor-not-allowed'
              }`}
          >
            {'>'}
          </button>
        </div>
      </div>
    </div>
  )
}
